/* MIT. Collection controls inherit the existing neutral merchant workspace. */
.collection-workspace {min-width:0}
.collection-source-form {display:grid;gap:16px}
.collection-fields {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.collection-fields>div {min-width:0}
.collection-options {font-size:12px}
.collection-options>summary {cursor:pointer;font-weight:600}
.collection-options .collection-fields {grid-template-columns:minmax(0,2fr) minmax(0,1fr);margin-top:14px}
.collection-upload-queue {border-top:1px solid var(--border);padding-top:16px}
.collection-upload-items {display:grid;gap:7px;margin:10px 0 15px;padding:0;list-style:none;max-height:230px;overflow:auto}
.collection-upload-items li {display:flex;justify-content:space-between;gap:15px;align-items:flex-start;font-size:12px}
.collection-upload-items strong {font-weight:550;overflow-wrap:anywhere;min-width:0}
.collection-upload-items span {font-size:11px;color:var(--muted);flex:0 0 auto}
.collection-upload-items button {font-size:10px;min-height:25px;padding:3px 6px;margin-left:8px}
.collection-workspace #collection-metrics {grid-template-columns:repeat(5,minmax(0,1fr))}
.collection-prepare-form {border-top:1px solid var(--border)}
.collection-prepare-form .hint {margin:0}
.collection-selected-heading {border-top:1px solid var(--border);padding-bottom:0}
.collection-selected-heading .history-detail {max-width:45%;min-width:0;text-align:right}
.collection-selected-heading .record-values {text-align:left}
.collection-progress {margin:16px 20px 0}
.collection-controls {padding-top:4px}
.collection-controls .hint {flex-basis:100%;margin:3px 0 0}
.collection-workspace .record-values {font-size:11px}
.collection-workspace td {overflow-wrap:anywhere}
.collection-workspace td:first-child:has(input[type=checkbox]) {width:38px}
.collection-workspace td input[type=checkbox],.collection-workspace th input[type=checkbox] {margin:3px 0;vertical-align:top}
.collection-workspace .record-detail .actions {margin-bottom:12px}
.collection-workspace .record-detail details {margin-top:14px}
.collection-publish {border-top:1px solid var(--border);display:grid;gap:13px}
.collection-publish .hint {margin-top:5px}
.collection-publish .table-wrap {border:1px solid var(--border);border-radius:3px}
.collection-publish .table-wrap:empty {display:none}
.collection-run-form {border-top:1px solid var(--border);padding-top:15px}
.collection-workspace .job-result {font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;max-width:460px}
.collection-workspace .native-reason {font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;margin-top:6px}
.collection-workspace .collection-filter-count {font-size:11px;color:var(--muted)}
@media(max-width:1150px) {
  .collection-workspace #collection-metrics {grid-template-columns:repeat(3,minmax(0,1fr))}
  .collection-fields {grid-template-columns:1fr 1fr}
  .collection-fields>div:last-child {grid-column:1/-1}
  .collection-options .collection-fields>div:last-child {grid-column:auto}
}
@media(max-width:760px) {
  .collection-workspace .table-wrap table {min-width:580px}
  .collection-workspace #collection-metrics {grid-template-columns:repeat(2,minmax(0,1fr))}
  .collection-fields,.collection-options .collection-fields {grid-template-columns:1fr}
  .collection-fields>div:last-child,.collection-options .collection-fields>div:last-child {grid-column:auto}
  .collection-selected-heading {flex-direction:column;gap:12px}
  .collection-selected-heading .history-detail {max-width:100%;width:100%;text-align:left}
  .collection-progress {margin:15px 15px 0}
  .collection-upload-items li {display:block}
  .collection-upload-items span {display:block;margin-top:3px}
  .collection-controls>button {flex:1 1 190px}
  .collection-workspace .panel-heading {flex-wrap:wrap}
  #collection-source-detail .record-values,#collection-result-detail .record-values {grid-template-columns:1fr;gap:4px}
  #collection-source-detail .record-values dd,#collection-result-detail .record-values dd {margin-bottom:8px}
}

// MIT. Operator controls over the original SF86 collection and accounting APIs.
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const endpoint = value => encodeURIComponent(value);
const shown = value => value === null || value === undefined ? 'Not recorded' : typeof value === 'object' ? JSON.stringify(value, null, 2) : String(value);
const friendly = value => String(value ?? '').toLowerCase().replace(/_/g, ' ').replace(/^./, char => char.toUpperCase());
const short = value => typeof value === 'string' && value.length > 25 ? value.slice(0, 13) + '…' + value.slice(-7) : shown(value);
const date = value => value ? new Date(value).toLocaleString(undefined, {dateStyle:'medium', timeStyle:'short'}) : 'Not recorded';
const network = value => ({'stellar:testnet':'Stellar testnet','stellar:pubnet':'Stellar public network'}[value] || shown(value));
const kind = value => ({'sf81-record':'Payment record · SF81','sf82-evidence':'Fulfilment evidence · SF82'}[value] || shown(value));
const verdict = value => ({UNATTEMPTED:'Unattempted',NOT_RECONCILED:'Needs reconciliation',CHAIN_TRANSFER_MATCHED_RPC_TESTNET:'Testnet transfer matched',CHAIN_TRANSFER_MATCHED_RPC_PUBNET:'Public network transfer matched',LOCAL_RPC_REPLAY_MATCHED:'Local RPC replay matched'}[value] || friendly(value));
const badge = (value, text = friendly(value)) => '<span class="badge" title="' + esc(value) + '">' + esc(text) + '</span>';
const active = job => ['queued','running','cancelling'].includes(job.status);
const PAGE = 25, FILE_LIMIT = 4_000_000;
const labels = {id:'Retained source ID',name:'Display name',kind:'Original source',payer:'Payer account',network:'Network',transaction:'Transaction',rpcEndpoint:'RPC endpoint',maxEventPages:'Maximum event pages',sha256:'Source SHA-256',bytes:'Retained bytes',createdAt:'Created',actor:'Operator',intentId:'Payment intent',sourceSha256:'Original source SHA-256',attempts:'Saved attempts',verdict:'Original verdict',reason:'Original reason',resultSha256:'Result SHA-256',batchId:'Original batch ID',planSha256:'Plan SHA-256',directory:'Retained collection directory',sourceIds:'Reviewed source IDs',completedAt:'Completed',lastJobId:'Last processed source',collectionId:'Collection ID',proofId:'Accounting verification file',sourceId:'Reviewed source ID',jobId:'Original source ID',included:'Included in accounting'};
const values = object => '<dl class="record-values">' + Object.entries(object).map(([key, value]) => '<dt>' + esc(labels[key] || key.replace(/([a-z])([A-Z])/g, '$1 $2')) + '</dt><dd' + (/(?:Id|Sha256|sha256|payer|transaction|rpcEndpoint)/.test(key) ? ' class="mono"' : '') + '>' + esc(key === 'network' ? network(value) : key === 'kind' ? kind(value) : key === 'createdAt' || key === 'completedAt' ? date(value) : shown(value)) + '</dd>').join('') + '</dl>';

