// MIT. Operator workflow over the original accounting and SF101 recovery engines.
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const shown = value => value === null || value === undefined ? 'Not recorded' : typeof value === 'object' ? JSON.stringify(value, null, 2) : String(value);
const date = value => value ? new Date(value).toLocaleString(undefined, {dateStyle:'medium',timeStyle:'short'}) : 'Not recorded';
const friendly = value => String(value ?? '').toLowerCase().replace(/_/g, ' ').replace(/^./, char => char.toUpperCase());
const encode = value => encodeURIComponent(value);
const definitions = pairs => '<dl class="record-values">' + pairs.map(([name,value]) => '<dt>' + esc(name) + '</dt><dd>' + esc(shown(value)) + '</dd>').join('') + '</dl>';
const definitionRows = pairs => pairs.map(([name,value]) => '<dt>' + esc(name) + '</dt><dd>' + esc(shown(value)) + '</dd>').join('');
const operationName = value => ({pause:'Pause workspace',review:'Review sources',backup:'Create backup',verify:'Verify backup',restore:'Restore operation',resume:'Reopen workspace'}[String(value).toLowerCase()] || friendly(value));
const errorText = value => typeof value === 'string' ? value : value?.message || value?.code || shown(value);
const active = job => job && ['QUEUED','RUNNING'].includes(job.status);

export async function mountRecovery({api, operator, onModeChange}) {
  const fragment = await fetch('/recovery.html', {cache:'no-store'});
  if (!fragment.ok) throw new Error('The backup and recovery interface could not be loaded.');
  $('area-maintenance').innerHTML = await fragment.text();
  let state = null, submitting = false, ordinaryBusy = false, selectedBackup = '', selectedJob = '', selectedJobDetail = null;
  let visible = false, limit = 12, poll = null, refreshPromise = null, previousMode = null, reviewId = '', backupIdentity = '';
  let pending = null, storageKey = '', loadedPending = false, disposed = false;
  const currentBackup = () => state?.backups?.find(item => item.id === selectedBackup);
  const activeJob = () => state?.jobs?.find(item => item.id === state.activeJobId) || state?.jobs?.find(active);
  function message(text, error = false) {
    $('maintenance-message').textContent = text;
    $('maintenance-message').hidden = !text;
    $('maintenance-message').classList.toggle('error', error);
  }
  function retainPending() {
    try { if (pending) sessionStorage.setItem(storageKey, JSON.stringify(pending)); else sessionStorage.removeItem(storageKey); } catch {}
  }
  function pendingControls() {
    $('maintenance-pending').hidden = !pending;
    $('maintenance-pending-description').textContent = pending ? operationName(pending.kind) + ' · ' + pending.body.requestId + '. Read its saved state or retry with the same request and inputs.' : '';
    $('maintenance-reconcile').disabled = $('maintenance-retry').disabled = submitting || !pending;
  }
  function controls() {
    const usable = Boolean(state?.configured) && !submitting && !ordinaryBusy && !pending;
    const idle = usable && !activeJob();
    const paused = ['PAUSED','RECOVERY_REQUIRED'].includes(state?.mode);
    const key = Boolean(state?.config?.passphraseConfigured);
    $('maintenance-pause').disabled = !idle || state.mode !== 'RUNNING';
    $('maintenance-resume').disabled = !idle || state.mode !== 'PAUSED';
    $('maintenance-refresh').disabled = submitting;
    $('maintenance-review').disabled = !idle || state.mode !== 'PAUSED';
    $('maintenance-backup-create').disabled = !idle || state.mode !== 'PAUSED' || !key || !state.review?.reviewId || !$('maintenance-backup-writers').checked;
    $('maintenance-verify').disabled = !idle || !key || !currentBackup();
    $('maintenance-restore').disabled = !idle || !paused || !key || !currentBackup() || !$('maintenance-restore-writers').checked || !$('maintenance-restore-confirm').checked;
    $('maintenance-restore').textContent = state?.mode === 'RECOVERY_REQUIRED' ? 'Continue recovery from this backup' : 'Restore selected backup';
    for (const button of $('area-maintenance').querySelectorAll('[data-maintenance-cancel]')) {
      const job = state?.jobs?.find(item => item.id === button.dataset.maintenanceCancel) || selectedJobDetail;
      button.disabled = submitting || Boolean(pending) || !active(job) || !job.cancellable || Boolean(job.cancelRequested);
    }
    pendingControls();
  }
  function renderConfiguration() {
    const mode = state.mode || 'RUNNING';
    const descriptions = {
      RUNNING:'Accounting is open. Pause the workspace before reviewing sources or capturing a backup.',
      PAUSING:'Finishing accepted accounting operations and closing their source owners. This page remains available.',
      PAUSED:'Accounting is paused. Review the current sources, create or verify a backup, or recover the retained operation.',
      RESUMING:'Reopening the original accounting sources and controllers.',
      RECOVERY_REQUIRED:'An original recovery is unfinished. Continue with its retained backup before reopening accounting.',
      CLOSING:'The server is finishing its accepted operation and closing.'
    };
    $('maintenance-mode').textContent = state.configured ? friendly(mode) : 'Not configured';
    $('maintenance-mode-description').textContent = state.configured ? descriptions[mode] || friendly(mode) : 'Accounting is available. Enable operating recovery in this host’s existing workspace configuration.';
    const config = state.config || {};
    const rows = [['Workspace',config.directory]];
    if (state.configured) rows.push(['Operating state root',config.stateRoot],['Backup folder',config.backupRoot],['Recovery key',config.passphraseConfigured ? 'Available on this host' : 'Set the configured host environment variable before backup or verification']);
    $('maintenance-config').innerHTML = definitionRows(rows);
    $('maintenance-setup').hidden = Boolean(state.configured);
    $('maintenance-workflow').hidden = !state.configured;
    $('maintenance-recovery-required').hidden = mode !== 'RECOVERY_REQUIRED';
    $('maintenance-recovery-values').innerHTML = definitionRows(Object.entries(state.recovery || {}).filter(([,value]) => value !== null && value !== undefined).map(([name,value]) => [friendly(name.replace(/([a-z])([A-Z])/g,'$1 $2')), value]));
  }
  function renderReview() {
    const review = state.review;
    if (reviewId !== (review?.reviewId || '')) {
      reviewId = review?.reviewId || '';
      $('maintenance-backup-writers').checked = false;
    }
    $('maintenance-review-detail').hidden = !review;
    $('maintenance-review-empty').hidden = Boolean(review);
    $('maintenance-review-empty').textContent = state.mode === 'PAUSED' ? 'Review the operating sources to prepare the next backup.' : 'Pause the workspace to review its operating sources.';
    if (!review) return;
    $('maintenance-review-values').innerHTML = definitionRows([
      ['Workspace revision',review.revision],['Operating files',review.operatingFiles],['Operating bytes',review.operatingBytes],
      ['Workspace SHA-256',review.workspaceSha256],['Review identity',review.reviewId]
    ]);
    const roots = Array.isArray(review.roots) ? review.roots.map((item,index) => [String(index + 1),item]) : Object.entries(review.roots || {});
    $('maintenance-roots').innerHTML = roots.map(([name,item]) => {
      const value = typeof item === 'string' ? {path:item} : item;
      return '<tr><td>' + esc(value.label || value.role || value.name || value.kind || name) + '</td><td>' + esc(value.path || value.directory || shown(item)) + '</td></tr>';
    }).join('');
    const auxiliary = review.additionalSources?.length ? review.additionalSources : review.auxiliaryInputs;
    $('maintenance-auxiliary').hidden = !auxiliary || (typeof auxiliary === 'number' ? auxiliary < 1 : Array.isArray(auxiliary) ? auxiliary.length === 0 : Object.keys(auxiliary).length === 0);
    $('maintenance-auxiliary-values').textContent = shown(auxiliary);
  }
  function renderBackups() {
    const backups = state.backups || [];
    if (!backups.some(item => item.id === selectedBackup)) selectedBackup = backups[0]?.id || '';
    const options = backups.length ? backups.map(item => '<option value="' + esc(item.id) + '">' + esc((item.label || item.id) + ' · ' + date(item.createdAt)) + '</option>').join('') : '<option value="">No retained backups</option>';
    const element = $('maintenance-backup-select');
    if (element.innerHTML !== options) element.innerHTML = options;
    element.value = selectedBackup;
    const backup = currentBackup();
    const identity = backup ? backup.id + ':' + backup.manifestSha256 : '';
    if (identity !== backupIdentity) {
      backupIdentity = identity;
      $('maintenance-restore-confirm').checked = $('maintenance-restore-writers').checked = false;
    }
    $('maintenance-backup-empty').hidden = Boolean(backup);
    $('maintenance-backup-detail').hidden = !backup;
    if (!backup) return;
    const folder = state.config?.backupRoot ? state.config.backupRoot.replace(/\/$/,'') + '/' + backup.id : backup.id;
    $('maintenance-backup-values').innerHTML = definitionRows([
      ['Name',backup.label || backup.id],['Created',date(backup.createdAt)],['Retained entries',backup.files],['Plaintext bytes',backup.bytes],
      ['Last verification',backup.verifiedAt ? date(backup.verifiedAt) : 'Not yet verified by this workspace'],
      ['Manifest SHA-256',backup.manifestSha256],['Host location',folder]
    ]);
    $('maintenance-restore-target').textContent = 'Workspace: ' + shown(state.config?.directory) + '. Operating root: ' + shown(state.config?.stateRoot) + '.';
  }
  function renderJobs() {
    const jobs = state.jobs || [];
    $('maintenance-job-count').textContent = String(state.jobsTotal ?? jobs.length) + ' retained';
    $('maintenance-jobs').innerHTML = jobs.slice(0,limit).map(job => '<tr' + (job.id === selectedJob ? ' class="selected"' : '') + '><td><button type="button" class="inspect" data-maintenance-job="' + esc(job.id) + '">' + esc(operationName(job.kind)) + '</button><span class="subtle mono">' + esc(job.id) + '</span></td><td>' + esc(date(job.startedAt || job.createdAt)) + '<span class="subtle">' + esc(job.actor || 'Not recorded') + '</span></td><td>' + esc(friendly(job.status)) + '<span class="subtle">' + esc(friendly(job.phase)) + '</span></td><td>' + (active(job) && job.cancellable ? '<button type="button" data-maintenance-cancel="' + esc(job.id) + '">' + (job.cancelRequested ? 'Stop requested' : 'Stop operation') + '</button>' : '') + '</td></tr>').join('') || '<tr><td colspan="4">No maintenance operations have been accepted.</td></tr>';
    $('maintenance-more').hidden = jobs.length <= limit;
    $('maintenance-history-description').textContent = 'Showing ' + Math.min(limit,jobs.length) + ' of ' + jobs.length + ' recent operations' + ((state.jobsTotal || 0) > jobs.length ? ' · ' + state.jobsTotal + ' retained on the host' : '') + '.';
    const job = activeJob();
    $('maintenance-progress').hidden = !job;
    $('maintenance-progress-title').textContent = job ? operationName(job.kind) : '';
    $('maintenance-progress-phase').textContent = job ? friendly(job.phase || job.status) : '';
    const current = jobs.find(item => item.id === selectedJob);
    if (current) selectedJobDetail = current;
    renderJobDetail();
  }
  function renderJobDetail() {
    const job = selectedJobDetail;
    const target = $('maintenance-job-detail');
    target.hidden = !job;
    if (!job) return;
    target.innerHTML = '<h3>' + esc(operationName(job.kind)) + '</h3>' + definitions([
      ['Operation',job.id],['Operator',job.actor],['State',friendly(job.status)],['Current phase',friendly(job.phase)],
      ['Accepted',date(job.createdAt)],['Started',date(job.startedAt)],['Finished',date(job.finishedAt)]
    ]) + (job.error ? '<div class="message error" role="alert">' + esc(errorText(job.error)) + '</div>' : '') +
      (job.result ? '<details open><summary>Retained result</summary><pre>' + esc(shown(job.result)) + '</pre></details>' : '') +
      (active(job) && job.cancellable ? '<div class="actions"><button type="button" data-maintenance-cancel="' + esc(job.id) + '">' + (job.cancelRequested ? 'Stop requested' : 'Stop operation') + '</button></div>' : '');
  }
  function schedule() {
    clearTimeout(poll);
    if (disposed || document.hidden || (!visible && !activeJob() && (!state?.configured || state.mode === 'RUNNING'))) return;
    poll = setTimeout(() => refresh().catch(error => { message(error.message, true); schedule(); }), activeJob() ? 1000 : 5000);
  }
  async function adopt(next) {
    state = next;
    if (!loadedPending) {
      storageKey = 'merchant-accounting.maintenance.' + String(next.config?.directory || location.origin);
      loadedPending = true;
      try {
        const saved = JSON.parse(sessionStorage.getItem(storageKey) || 'null');
        if (saved?.body?.requestId && saved.path?.startsWith('/api/maintenance/')) pending = saved;
      } catch {}
    }
    const existing = pending && state.jobs?.find(item => item.id === pending.body.requestId);
    if (existing) { selectedJob = existing.id; selectedJobDetail = existing; pending = null; retainPending(); }
    renderConfiguration(); renderReview(); renderBackups(); renderJobs(); controls();
    const changed = previousMode !== state.mode;
    const prior = previousMode;
    previousMode = state.mode;
    if (changed) await onModeChange?.(state, prior);
    schedule();
  }
  async function refresh() {
    if (refreshPromise) return refreshPromise;
    refreshPromise = (async () => { await adopt(await api('/api/maintenance')); return state; })();
    try { return await refreshPromise; } finally { refreshPromise = null; }
  }
  async function send(command) {
    if (submitting) return;
    submitting = true; controls();
    try {
      const result = await api(command.path, command.body);
      if (!result.job || !result.state) throw new Error('The operation response was incomplete. Read its retained command before continuing.');
      selectedJob = result.job.id; selectedJobDetail = result.job;
      pending = null; retainPending();
      await adopt(result.state);
      message(operationName(command.kind) + ' accepted. The original operation and its result remain in the history.');
    } catch (error) {
      if (error.status && error.status < 500) { pending = null; retainPending(); }
      message(error.message || String(error), true);
      try { await refresh(); } catch {}
    } finally { submitting = false; controls(); schedule(); }
  }
  async function action(kind, body = {}, suffix = kind) {
    if (pending) throw new Error('Read or retry the retained command before starting another operation.');
    const actor = operator();
    if (actor.length > 160) throw new Error('Use an operator reference of at most 160 characters for recovery.');
    pending = {kind,path:'/api/maintenance/' + suffix,body:{...body,actor,requestId:crypto.randomUUID()}};
    retainPending(); await send(pending);
  }
  function attempt(work) {
    return Promise.resolve().then(work).catch(error => message(error.message || String(error), true));
  }
  async function reconcilePending() {
    if (!pending) return;
    const result = await api('/api/maintenance/jobs/' + encode(pending.body.requestId));
    const job = result.job || result;
    if (!job?.id) throw new Error('The retained operation could not be read.');
    selectedJob = job.id; selectedJobDetail = job;
    pending = null; retainPending();
    await refresh();
    message('Loaded the original saved operation.');
  }
  $('maintenance-pause').addEventListener('click',() => attempt(() => action('pause')));
  $('maintenance-resume').addEventListener('click',() => attempt(() => action('resume')));
  $('maintenance-refresh').addEventListener('click',() => attempt(refresh));
  $('maintenance-review').addEventListener('click',() => attempt(() => action('review')));
  $('maintenance-backup-form').addEventListener('submit',event => { event.preventDefault(); attempt(async () => {
    if (!$('maintenance-backup-writers').checked || !state?.review?.reviewId) throw new Error('Review the sources and stop their external writers before capture.');
    await action('backup',{expectedReviewId:state.review.reviewId,externalWritersStopped:true,label:$('maintenance-backup-label').value.trim()});
  }); });
  $('maintenance-backup-select').addEventListener('change',() => { selectedBackup = $('maintenance-backup-select').value; renderBackups(); controls(); });
  $('maintenance-verify').addEventListener('click',() => attempt(async () => {
    const backup = currentBackup(); if (!backup) throw new Error('Choose a retained backup.');
    await action('verify',{backupId:backup.id,expectedSha256:backup.manifestSha256});
  }));
  $('maintenance-restore-form').addEventListener('submit',event => { event.preventDefault(); attempt(async () => {
    const backup = currentBackup();
    if (!backup || !$('maintenance-restore-writers').checked || !$('maintenance-restore-confirm').checked) throw new Error('Review the selected backup, original target and stopped source writers before recovery.');
    await action('restore',{backupId:backup.id,expectedSha256:backup.manifestSha256,externalWritersStopped:true});
  }); });
  for (const id of ['maintenance-backup-writers','maintenance-restore-writers','maintenance-restore-confirm']) $(id).addEventListener('change',controls);
  $('maintenance-more').addEventListener('click',() => { limit += 12; renderJobs(); controls(); });
  $('area-maintenance').addEventListener('click',event => {
    const inspect = event.target.closest('[data-maintenance-job]');
    if (inspect) {
      selectedJob = inspect.dataset.maintenanceJob;
      selectedJobDetail = state.jobs.find(item => item.id === selectedJob) || null;
      renderJobs(); controls(); $('maintenance-job-detail').focus({preventScroll:true});
    }
    const cancel = event.target.closest('[data-maintenance-cancel]');
    if (cancel) attempt(() => action('cancel',{},'jobs/' + encode(cancel.dataset.maintenanceCancel) + '/cancel'));
  });
  $('maintenance-reconcile').addEventListener('click',() => attempt(reconcilePending));
  $('maintenance-retry').addEventListener('click',() => attempt(() => pending && send(pending)));
  document.addEventListener('visibilitychange',() => { if (document.hidden) clearTimeout(poll); else attempt(refresh); });
  await refresh();
  return {
    refresh,
    setVisible(value) { visible = value; if (value) attempt(refresh); else schedule(); },
    setBusy(value) { ordinaryBusy = value; controls(); },
    getState() { return state; },
    close() { disposed = true; clearTimeout(poll); }
  };
}

:root {font:14px/1.5 ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#23282c;background:#f3f4f4;--border:#d4d9dc;--muted:#626b72;--soft:#f6f7f7;--ink:#252c31}
* {box-sizing:border-box}
body {margin:0}
a {color:inherit;text-underline-offset:2px}
button,input,select,textarea {font:inherit;color:inherit}
button,.button {display:inline-flex;align-items:center;justify-content:center;min-height:35px;padding:7px 12px;border:1px solid #b8c0c5;border-radius:3px;background:#fff;color:inherit;line-height:1.3;font-weight:550;text-decoration:none;cursor:pointer}
button:hover,.button:hover {background:#e9edef;border-color:#89949b}
button:disabled,.tabs a[aria-disabled="true"] {opacity:.45;cursor:default}
button.primary {color:#fff;background:var(--ink);border-color:var(--ink)}
button.primary:hover {background:#414b52}
button.quiet {background:transparent;border-color:transparent}
input,select,textarea {width:100%;min-width:0;max-width:100%;padding:8px 9px;border:1px solid #b9c1c6;border-radius:3px;background:#fff}
input[type=file] {font-size:12px}
input[type=checkbox] {width:16px;height:16px;min-width:16px;accent-color:var(--ink)}
textarea {resize:vertical}
label {display:block;font-size:12px;font-weight:600;margin:0 0 5px}
h1,h2,h3,p {margin:0}
h1 {font-size:26px;line-height:1.3;font-weight:600;letter-spacing:-.6px}
h2 {font-size:16px;font-weight:650;line-height:1.4}
h3 {font-size:14px;font-weight:650}
.hint,.subtle,.panel-heading p,.heading p {font-size:12px;color:var(--muted)}
.hint {margin-top:5px}
.mono {font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:11px;overflow-wrap:anywhere}
.topbar {height:55px;padding:0 24px;display:flex;align-items:center;justify-content:space-between;gap:20px;background:var(--ink);color:#fff}
.topbar strong {font-size:11px;letter-spacing:1px}
.topbar strong span {margin:0 10px;color:#adb6bc}
.topbar>span {font-size:12px;color:#e0e5e8}
.layout {display:grid;grid-template-columns:254px minmax(0,1fr);min-height:calc(100vh - 55px)}
.sidebar {border-right:1px solid var(--border);padding:24px 17px;background:#e9edef;display:flex;flex-direction:column;align-items:stretch;min-width:0}
.sidebar #refresh {margin:17px 0 23px}
.side-title {font-size:11px;text-transform:uppercase;font-weight:650;letter-spacing:1px;margin-bottom:10px}
.run-list {display:flex;flex-direction:column;gap:7px}
.sidebar #run-search {margin:0 0 10px;font-size:12px}
.sidebar #run-more {margin-top:10px;font-size:11px}
.run-list button {display:block;min-width:0;text-align:left;font-size:12px;padding:11px 10px;font-weight:500;background:#f8f9f9}
.run-list button.selected {border-left:3px solid var(--ink);background:#fff;padding-left:8px}
.run-list button strong {display:block;font-size:12px;overflow-wrap:anywhere}
.run-list button span {display:block;font-size:10px;color:var(--muted);margin-top:4px}
.sidebar-foot {margin-top:auto;padding-top:30px;color:var(--muted);font-size:11px}
main {padding:29px 30px 60px;min-width:0;max-width:1600px;width:100%}
.heading {display:flex;justify-content:space-between;align-items:flex-start;gap:15px;margin-bottom:22px}
.heading p {margin-top:7px;max-width:720px}
.eyebrow {font-size:10px;letter-spacing:.9px;text-transform:uppercase;color:var(--muted);font-weight:650;margin-bottom:8px}
.badge {display:inline-block;border:1px solid #bcc5cb;border-radius:3px;padding:4px 8px;font-size:10px;font-weight:600;background:#f0f3f4;line-height:1.4}
.badge.strong {background:#364148;border-color:#364148;color:#fff}
.tabs,.table-tabs {display:flex;gap:23px;border-bottom:1px solid #bcc5cb;overflow-x:auto}
.tabs {margin-bottom:23px}
.tabs button,.tabs a,.table-tabs button {border:0;border-bottom:3px solid transparent;border-radius:0;padding:12px 0;color:var(--muted);background:transparent;white-space:nowrap;font-size:12px}
.tabs button.active,.table-tabs button.active {border-bottom-color:var(--ink);color:var(--ink);font-weight:650}
.panel {background:#fff;border:1px solid var(--border);border-radius:3px;margin-bottom:20px;overflow:hidden}
.panel-heading {padding:18px 20px;border-bottom:1px solid #e0e5e7;display:flex;align-items:flex-start;justify-content:space-between;gap:14px}
.panel-heading p {margin-top:5px;max-width:740px}
.padded {padding:18px 20px}
.inline-form {display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.inline-form label {margin:0}
.inline-form input,.inline-form select {flex:1;min-width:190px}
.actions {display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.metrics {display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;background:var(--border);border:1px solid var(--border);border-radius:3px;overflow:hidden;margin:17px 0 12px}
.metric {background:#fff;padding:15px;min-width:0}
.metric span {display:block;font-size:11px;color:var(--muted);margin-bottom:6px}
.metric strong {display:block;font-size:23px;font-weight:600;overflow-wrap:anywhere;line-height:1.25}
.metrics.inset {margin:18px 20px}
.summary-note {margin:0 0 19px}
.selected-heading {display:flex;justify-content:space-between;align-items:flex-start;gap:15px;padding:3px 0}
.selected-heading p {margin-top:4px}
.progress {display:flex;align-items:center;gap:14px;padding:14px 18px;border:1px solid var(--border);background:#e9edef;font-size:12px;margin:16px 0}
.progress progress {width:120px;accent-color:#4b5a63}
.table-tabs {gap:22px;padding:0 18px;border-bottom:1px solid var(--border)}
.filters {display:flex;align-items:center;flex-wrap:wrap;gap:9px;padding:12px 18px;border-bottom:1px solid var(--border);background:#f8f9f9}
.filters label {margin:0}
.filters input {flex:1;min-width:150px}
.filters select {width:auto;max-width:160px;font-size:12px}
.filters button {font-size:12px}
.record-layout {display:grid;grid-template-columns:minmax(320px,58%) minmax(0,1fr)}
.records {border-right:1px solid var(--border);min-width:0}
.table-wrap {max-width:100%;overflow-x:auto}
table {width:100%;border-collapse:collapse;text-align:left;font-size:12px}
th,td {padding:11px 12px;border-bottom:1px solid #e1e6e9;vertical-align:top}
th {background:#f4f6f7;color:#505e68;font-size:10px;font-weight:650;white-space:nowrap}
tbody tr:last-child td {border-bottom:0}
tr.selected {background:#edf1f3}
td .subtle {display:block;font-size:10px;margin-top:4px}
td button,td .button {font-size:11px;padding:5px 8px;min-height:30px}
td .badge {font-size:9px}
.record-detail {padding:19px;min-width:0}
.inspect {text-align:left;justify-content:flex-start;overflow-wrap:anywhere;max-width:100%}
.exact {font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:11px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.records td {overflow-wrap:anywhere}
.record-detail h3 {margin-bottom:12px;overflow-wrap:anywhere}
.record-values {display:grid;grid-template-columns:minmax(95px,34%) minmax(0,1fr);gap:9px 15px;font-size:11px;margin:12px 0 20px}
.record-values dt {color:var(--muted);overflow-wrap:anywhere}
.record-values dd {margin:0;overflow-wrap:anywhere}
.record-detail form {border-top:1px solid var(--border);padding-top:14px}
.record-detail form label {margin-top:12px}
.record-detail form label:first-child {margin-top:0}
.record-detail form .actions {margin-top:14px}
.review-by {border-top:1px solid #e0e5e8;margin-top:16px;padding-top:10px;font-size:11px;color:var(--muted)}
.review-by details {margin-top:8px}
.review-by summary {cursor:pointer}
.review-by p {margin-top:8px;white-space:pre-wrap;overflow-wrap:anywhere}
.pagination {padding:11px 13px;border-top:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:11px}
.pagination button {font-size:11px;min-height:31px;padding:6px 9px}
.source-paths {display:grid;grid-template-columns:170px minmax(0,1fr);gap:14px 18px;margin:0;font-size:12px}
.source-paths dt {font-weight:600}
.source-paths dd {margin:0;overflow-wrap:anywhere}
.upload-form {display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px 12px;border-top:1px solid #e1e6e9}
.upload-form label {grid-column:1/-1;margin:0}
.upload-form button {align-self:start}
.compare-form {display:grid;grid-template-columns:1fr 1fr 190px auto;gap:12px;align-items:end}
.compare-form select {font-size:12px}
.change-values {max-width:300px;overflow-wrap:anywhere;font-size:11px}
.change-values div+div {margin-top:5px}
.changes {margin:0;display:grid;gap:3px;font-size:11px}
.changes dt {color:var(--muted);margin-top:7px;font-size:10px}
.changes dt:first-child {margin-top:0}
.changes dd {margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}
#compare-metrics {grid-template-columns:repeat(auto-fit,minmax(130px,1fr))}
.check-label {display:flex;align-items:flex-start;gap:9px;font-size:12px;font-weight:400;margin:17px 0}
.check-label input {margin-top:2px}
.download-links {display:flex;gap:9px;flex-wrap:wrap}
.download-links .button {font-size:12px}
.history-detail summary {font-size:11px;cursor:pointer}
.history-detail pre {white-space:pre-wrap;overflow-wrap:anywhere;font-size:10px;max-height:220px;overflow:auto}
.message {padding:13px 16px;border:1px solid #aebbc3;background:#eaf0f3;border-radius:3px;margin-bottom:18px;font-size:13px;overflow-wrap:anywhere}
.message.error {background:#f4f1ed;border-left:4px solid #424e57}
.conflict {padding:14px 16px;border:1px solid #909da6;border-left:4px solid #333e46;background:#f2f1ed;border-radius:3px;margin-bottom:19px;display:flex;justify-content:space-between;gap:20px}
.conflict strong {font-size:13px}
.conflict p {font-size:12px;margin-top:5px}
.conflict .actions {max-width:45%;flex-shrink:0}
.conflict button {font-size:11px}
.empty {padding:38px 23px;text-align:center;color:var(--muted);font-size:13px}
.empty h2 {color:var(--ink);margin-bottom:9px}
.empty p {max-width:550px;margin:0 auto 17px}
.empty button {margin-top:8px}
[hidden] {display:none!important}
.sr-only {position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.skip {position:absolute;left:16px;top:-80px;background:#fff;color:#111;padding:8px 12px;z-index:10}
.skip:focus {top:9px}
:focus-visible {outline:2px solid #25353f;outline-offset:3px}
body.working {cursor:progress}
.source-connect {display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;align-items:start}
.source-connect button {margin-top:23px}
.recovery-source-actions {padding-top:0}
.recovery-form label:not(:first-child) {margin-top:16px}
.recovery-form .actions {margin-top:17px}
.recovery-form textarea {font-size:12px;line-height:1.55}
#recovery-preview-detail {margin:16px 0;max-width:100%;overflow-wrap:anywhere}
#recovery-preview-detail .record-values {grid-template-columns:minmax(130px,24%) minmax(0,1fr);font-size:12px}
.record-values dd {white-space:pre-wrap}
.recovery-progress {margin:15px 20px}
.recovery-native-result {white-space:pre-wrap;overflow-wrap:anywhere;max-width:500px;font-size:11px}
#recovery-entries td,#recovery-jobs td {overflow-wrap:anywhere}
#recovery-entry-detail .actions {margin-bottom:15px}
#recovery-preview-select {max-width:760px}
@media(max-width:1150px) {
  .layout {grid-template-columns:225px minmax(0,1fr)}
  main {padding:25px 22px 50px}
  .metrics {grid-template-columns:repeat(2,minmax(0,1fr))}
  .record-layout {grid-template-columns:1fr}
  .records {border-right:0;border-bottom:1px solid var(--border)}
  .compare-form {grid-template-columns:1fr 1fr}
  .compare-form button {height:38px}
  .conflict {flex-direction:column}
  .conflict .actions {max-width:none}
}
@media(max-width:760px) {
  .source-connect {grid-template-columns:1fr}
  .source-connect button {margin:0}
  #recovery-preview-detail .record-values {grid-template-columns:1fr;gap:4px}
  #recovery-preview-detail .record-values dd {margin-bottom:8px}
  .recovery-progress {margin:15px}
  .topbar {height:49px;padding:0 18px}
  .topbar strong {font-size:10px}
  .topbar>span {display:none}
  .layout {display:block}
  .sidebar {padding:16px 18px;border-right:0;border-bottom:1px solid var(--border);display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px 12px}
  .sidebar label {grid-column:1/-1;margin:0}
  .sidebar #refresh {margin:0;grid-row:2;grid-column:2;font-size:11px}
  .sidebar .hint {grid-column:1/-1;margin:0}
  .side-title {margin:14px 0 2px;grid-column:1/-1}
  .run-list {grid-column:1/-1;flex-direction:row;overflow-x:auto;padding-bottom:4px;max-height:130px}
  .sidebar #run-search,.sidebar #run-more {grid-column:1/-1}
  .run-list button {flex:0 0 175px}
  .sidebar-foot {display:none}
  main {padding:22px 17px 40px}
  .heading .badge {max-width:100px;text-align:center}
  .heading {gap:12px}
  h1 {font-size:23px}
  .eyebrow {font-size:9px;letter-spacing:.6px}
  .tabs {gap:18px}
  .tabs button,.tabs a {font-size:11px}
  .panel-heading,.padded {padding:15px}
  .inline-form {align-items:stretch}
  .inline-form label {width:100%}
  .inline-form input,.inline-form select {min-width:100%;flex:1}
  .inline-form button {width:100%}
  .table-tabs {gap:19px;padding:0 13px}
  .table-tabs button {font-size:11px}
  .filters {padding:11px 13px}
  .filters input {min-width:140px}
  .filters select {max-width:175px;flex:1}
  .metric {padding:12px}
  .metric strong {font-size:21px}
  .record-detail {padding:15px}
  th,td {padding:10px}
  .source-paths {grid-template-columns:1fr;gap:4px;font-size:11px}
  .source-paths dd {margin-bottom:12px}
  .upload-form {grid-template-columns:1fr}
  .upload-form button {width:100%}
  .compare-form {grid-template-columns:1fr}
  .progress {align-items:flex-start;flex-direction:column;font-size:11px}
  .pagination {flex-wrap:wrap}
  .selected-heading {gap:10px}
  .selected-heading h2 {font-size:15px}
}

/* Plain operator controls; inherits the original accounting workspace typography. */
:root{color-scheme:light}
body{background:#f2f3f4;color:#1d2023;margin:0}
.topbar{background:#fff;border-bottom:1px solid #c9cdd1;display:flex;align-items:center;justify-content:space-between;gap:24px;padding:22px 28px}
.topbar h1{font-size:24px;margin:0}.eyebrow{margin:0 0 5px;font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#62686d}
a{color:#30383e;text-underline-offset:3px}
.xero-shell{display:grid;grid-template-columns:230px minmax(0,1fr);max-width:1600px;margin:auto;gap:24px;padding:24px}
.xero-sidebar{position:sticky;top:24px;align-self:start;display:grid;gap:16px}.xero-sidebar nav{display:grid;gap:10px;padding:18px 0;border-top:1px solid #c9cdd1;border-bottom:1px solid #c9cdd1}
.xero-content{min-width:0;display:grid;gap:24px}
.panel{background:#fff;border:1px solid #c9cdd1;border-radius:3px;padding:24px;min-width:0}
.panel h2{font-size:19px;margin:0 0 12px}.panel h3{font-size:16px;margin:24px 0 12px}
p{line-height:1.5}.muted{color:#646a70;font-size:13px}.xero-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
label{display:grid;gap:6px;font-weight:600;font-size:13px;margin:12px 0}
input,select,textarea{font:inherit;background:#fff;color:#1d2023;border:1px solid #afb5bb;border-radius:2px;padding:10px;min-width:0;width:100%;box-sizing:border-box}
textarea{resize:vertical}input[type=checkbox]{width:17px;height:17px;flex:none}.xero-check{display:flex;gap:10px;align-items:center;font-weight:400}
button{background:#30373d;color:#fff;border:1px solid #30373d;border-radius:2px;padding:10px 14px;min-height:40px;cursor:pointer;font-weight:600}button:disabled{background:#e6e8ea;border-color:#cdd1d5;color:#747a80;cursor:default}
button:hover:not(:disabled){background:#171c20}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid #111;outline-offset:3px}
.xero-actions,.xero-heading{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:flex-start;margin:16px 0}.xero-heading{justify-content:space-between}
#notice{padding:16px;background:#fff;border:2px solid #515960;white-space:pre-wrap}#notice[data-error=true]{border-style:double}
.xero-component{margin:18px 0;padding:18px;border:1px solid #c9cdd1;background:#fafafa}.xero-component h4{margin:0 0 8px;font-size:14px}.xero-component .source{font-size:12px;overflow-wrap:anywhere;color:#555c62}.xero-component[aria-disabled=true]{background:#f0f1f2}
.xero-scroll{max-width:100%;overflow:auto;margin:14px 0}table{border-collapse:collapse;font-size:13px;width:100%}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #d9dcdf;padding:10px;overflow-wrap:anywhere}th{background:#f2f3f4;font-weight:600}td.num,th.num{text-align:right;font-variant-numeric:tabular-nums}
details{margin:12px 0}summary{cursor:pointer;font-weight:600}pre{overflow:auto;max-height:420px;background:#f2f3f4;padding:14px;border:1px solid #d9dcdf;font-size:12px;line-height:1.5}
.xero-badge{display:inline-block;background:#edf0f2;border:1px solid #c9cdd1;padding:3px 6px;font-size:11px;line-height:1.4;margin:3px}
.xero-links{display:flex;flex-wrap:wrap;gap:14px;margin:18px 0}.xero-callout{padding:12px;border-left:3px solid #737b81;background:#f2f3f4}
[hidden]{display:none!important}
@media(max-width:850px){.xero-shell{grid-template-columns:1fr;padding:14px}.xero-sidebar{position:static;display:flex;flex-wrap:wrap;align-items:center}.xero-sidebar>label{flex:1}.xero-sidebar nav{display:flex;flex-wrap:wrap;width:100%}.xero-sidebar p{margin:0}.panel{padding:18px}.xero-grid{grid-template-columns:1fr}.topbar{padding:18px;align-items:start}}

// MIT. Original accounting workspace Xero operator workflow.
const $=id=>document.getElementById(id);
let state,source,preview,detail,comparison,returnPreview,operationTimer,busy=false;
const actor=$('actor');
actor.value=localStorage.getItem('merchant-accounting-xero-actor')??'';
actor.addEventListener('change',()=>localStorage.setItem('merchant-accounting-xero-actor',actor.value.trim()));
function operator(){const value=actor.value.trim();if(!value)throw Error('Enter the operator name first.');return value;}
function notice(message,error=false){$('notice').textContent=message;$('notice').dataset.error=String(error);$('notice').hidden=false;}
function node(tag,text,attributes={}){const el=document.createElement(tag);if(text!==undefined&&text!==null)el.textContent=String(text);for(const [key,value]of Object.entries(attributes))el.setAttribute(key,String(value));return el;}
function jsonDetails(label,value){const el=node('details');el.append(node('summary',label),node('pre',JSON.stringify(value,null,2)));return el;}
function table(headers,rows){const wrap=node('div',null,{class:'xero-scroll'}),el=node('table'),thead=node('thead'),tr=node('tr');for(const header of headers)tr.append(node('th',header));thead.append(tr);el.append(thead);const body=node('tbody');for(const row of rows){const rowEl=node('tr');for(const value of row){const td=node('td');if(value instanceof Node)td.append(value);else td.textContent=value??'';rowEl.append(td);}body.append(rowEl);}el.append(body);wrap.append(el);return wrap;}
function options(select,rows,label,selected){select.replaceChildren(node('option','Choose…',{value:''}));for(const row of rows)select.append(node('option',label(row),{value:row.id}));if(rows.some(row=>row.id===selected))select.value=selected;}
function summary(plan){const result=node('div');result.append(node('p',plan.name+' · '+plan.context.organization.name+' · '+plan.context.organization.baseCurrency));result.append(jsonDetails('Journal summary and source',plan.summary));result.append(table(['Journal date','Narration','Lines','Total debits','State'],plan.journals.map(journal=>[journal.date,journal.narration,journal.payload?.JournalLines?.length??journal.lines?.length,journal.debitTotal??journal.total??'',journal.payload?.Status??'DRAFT'])));for(const journal of plan.journals)result.append(jsonDetails('Native draft · '+journal.narration,journal.payload));if(plan.excluded?.length)result.append(jsonDetails('Explicit source exclusions',plan.excluded));return result;}
async function api(path,value){const response=await fetch(path,{method:value===undefined?'GET':'POST',cache:'no-store',headers:value===undefined?{}:{'Content-Type':'application/json','X-Workspace-Request':'1'},...(value===undefined?{}:{body:JSON.stringify(value)})});let result;try{result=await response.json();}catch{throw Error('The local workspace did not return a JSON response.');}if(!response.ok)throw Error(result.message??result.error??'Workspace request failed.');return result;}
async function action(fn){if(busy)return;busy=true;document.body.setAttribute('aria-busy','true');try{return await fn();}catch(error){notice(error.message??String(error),true);}finally{busy=false;document.body.removeAttribute('aria-busy');}}
async function encoded(file){if(!file)throw Error('Choose the original JSON response file.');if(file.size>64_000_000)throw Error('Use an original source response of at most 64 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(binary);}
function record(){return detail?.record;}
function selectedPlan(){if(!$('plans').value)throw Error('Choose a saved journal plan.');return $('plans').value;}
function planPath(){return '/api/xero/plans/'+encodeURIComponent(selectedPlan());}
function capturePath(){if(!$('capture').value)throw Error('Choose a retained comparison.');return planPath()+'/captures/'+encodeURIComponent($('capture').value);}
function clearReturn(){returnPreview=null;$('return').hidden=true;}
function managedConnection(){const value=state?.connection?.authorization;return value?.kind==='oauth-connection'?value:null;}
function connectionAvailable(tenantId){const managed=managedConnection();return Boolean(state?.connection?.available)&&(!tenantId||!managed||managed.tenantId===tenantId);}
function renderConnection(){
  const selected=managedConnection(),form=$('context-form');
  $('connection').textContent=selected?
    (selected.organizationName??selected.tenantName??'Selected Xero organization')+' · '+(selected.baseCurrency??'')+' · '+(selected.isDemoCompany?'Demo organization':'Merchant books')+' · '+selected.state:
    connectionAvailable()?'Xero connection configured in the server process.':'Native source import is available. Configure the Xero connection in the server process for API reads and draft creation.';
  $('managed-connection').hidden=!selected;
  if(selected){
    form.elements.tenantId.value=selected.tenantId;
    if(!form.elements.name.value.trim())form.elements.name.value=(selected.organizationName??selected.tenantName??'Xero organization').slice(0,160);
    $('managed-connection-content').replaceChildren(table(['Selected field','Value'],[
      ['Connection',selected.alias],['Organization',selected.organizationName??selected.tenantName],
      ['Tenant ID',selected.tenantId],['Connection ID',selected.connectionId],['Authorization state',selected.state],
      ['Selection SHA256',selected.selectionSha256],['Native tenant read',selected.lastTenantReadAt??''],
    ]));
    if(selected.lastError)$('managed-connection-content').append(node('p','Connection: '+selected.lastError));
  }
  form.elements.tenantId.readOnly=Boolean(selected);
  document.querySelector('#context-form button[value="capture"]').disabled=!connectionAvailable();
}
async function refresh(){
  const oldHandoff=$('handoff').value,oldContext=$('context').value,oldPlan=$('plans').value;
  state=await api('/api/xero');
  $('workspace-revision').textContent='Workspace revision '+state.revision;
  renderConnection();
  options($('handoff'),state.handoffs,row=>row.name+' · '+row.id.slice(0,8),oldHandoff);
  options($('context'),state.contexts,row=>row.name+' · '+(row.baseCurrency??row.organization?.baseCurrency??'')+' · '+row.id.slice(0,8),oldContext);
  options($('plans'),state.plans,row=>row.name+' · '+(row.cancelledAt?'CANCELLED':row.createdAt??row.id.slice(0,8)),oldPlan);
  $('contexts').replaceChildren(table(['Organization','Base currency','Account source','Recorded'],state.contexts.map(row=>[row.name,row.baseCurrency??row.organization?.baseCurrency??'',row.accountCount??'',row.createdAt??''])));
  document.querySelector('#context-form button[value="capture"]').disabled=!connectionAvailable();
}
function labelled(text,input){const label=node('label',text);label.append(input);return label;}
function input(name,{value='',required=false,type='text',placeholder='',maxLength}={}){const element=node('input',null,{name,type});element.value=value;element.required=required;element.placeholder=placeholder;if(maxLength)element.maxLength=maxLength;return element;}
function accountSelect(name,accounts){const el=node('select',null,{name});el.required=true;el.append(node('option','Choose an account',{value:''}));for(const account of accounts)el.append(node('option',account.code+' · '+account.name,{value:account.code}));return el;}
function renderSource(){
  $('components').replaceChildren();$('source-summary').textContent=source.components.length+' original payment or verified refund components. Choose an accounting treatment for each.';
  $('plan-form').elements.purpose.value=source.context.organization.isDemoCompany?'demo':'books';
  $('plan-form').elements.name.value=source.handoff.name+' · Xero';
  const accounts=source.context.accounts.filter(account=>account.eligible);
  for(const [index,component]of source.components.entries()){
    const article=node('article',null,{class:'xero-component','data-component':component.id});
    article.append(node('h4',(index+1)+'. '+component.kind+' · '+component.eventId),node('p','Original '+component.amountAtomic+' atomic units · '+component.network,{class:'source'}),jsonDetails('Original component',component));
    const decision=node('select',null,{name:'decision'});decision.append(node('option','Choose treatment',{value:''}),node('option','Include in journals',{value:'include'}),node('option','Exclude with a reason',{value:'exclude'}));decision.required=true;article.append(labelled('Accounting treatment',decision));
    const included=node('div',null,{'data-included':'1',hidden:''}),excluded=node('div',null,{'data-excluded':'1',hidden:''});
    const first=node('div',null,{class:'xero-grid'}),second=node('div',null,{class:'xero-grid'});
    first.append(labelled('Value in '+source.context.organization.baseCurrency,input('amount',{placeholder:'0.00',required:true})),labelled('Journal date',input('date',{type:'date',value:component.sourceAt?.slice(0,10)??'',required:true})));
    second.append(labelled('Debit account',accountSelect('debitAccountCode',accounts)),labelled('Credit account',accountSelect('creditAccountCode',accounts)));
    included.append(first,second,labelled('Valuation source for this component',input('valuationNote',{required:true,maxLength:2000})),labelled('Description',input('description',{value:component.kind+' '+component.eventId,maxLength:2000})));
    excluded.append(labelled('Exclusion reason',input('reason',{required:true,maxLength:2000})));
    function treatment(){included.hidden=decision.value!=='include';excluded.hidden=decision.value!=='exclude';for(const control of included.querySelectorAll('input,select'))control.disabled=included.hidden;for(const control of excluded.querySelectorAll('input'))control.disabled=excluded.hidden;invalidatePreview();}
    decision.addEventListener('change',treatment);article.append(included,excluded);$('components').append(article);treatment();
  }
  $('plan-form').hidden=false;invalidatePreview();
}
function invalidatePreview(){preview=null;$('preview').hidden=true;}
$('actor').addEventListener('input',()=>{invalidatePreview();clearReturn();});
$('plan-form').addEventListener('input',invalidatePreview);
$('handoff').addEventListener('change',()=>{source=null;$('plan-form').hidden=true;invalidatePreview();});
$('context').addEventListener('change',()=>{source=null;$('plan-form').hidden=true;invalidatePreview();});
$('refresh').addEventListener('click',()=>action(refresh));
$('context-form').addEventListener('submit',event=>{event.preventDefault();action(async()=>{
  const form=event.currentTarget,request={id:crypto.randomUUID(),revision:state.revision,actor:operator(),name:form.elements.name.value.trim(),tenantId:form.elements.tenantId.value.trim()};
  if(event.submitter.value==='import'){request.organizationBase64=await encoded(form.elements.organizationFile.files[0]);request.accountsBase64=await encoded(form.elements.accountsFile.files[0]);}
