  requireValue(typeof maxAtomic === 'string' && /^[1-9][0-9]*$/.test(maxAtomic) &&
    maxAtomic.length <= 39 && BigInt(maxAtomic) <= 170141183460469231731687303715884105727n,
    'MAX_ATOMIC_I128_REQUIRED');
